"use client";
import Link from "next/link";
import { ArrowRight, Eye, ImagePlus, Package, Plus, ReceiptText, Settings2, Store, TrendingUp } from "lucide-react";
import { StoreHeader } from "@/components/store/store-header";
import { BottomNav } from "@/components/store/bottom-nav";
import { PortalSwitcher } from "@/components/shared/portal-switcher";
import { products, money } from "@/lib/catalog";
import { useAuth } from "@/hooks/use-auth";
import { Thumb } from "@/components/shared/thumb";

export default function VendorPage() {
  const user = useAuth((s) => s.user); const hydrated = useAuth((s) => s.hydrated); const vendorRegistered = useAuth((s) => s.vendorRegistered);
  if (!hydrated) return <PageFrame><div className="grid min-h-[60vh] place-items-center text-sm text-ink-muted">Checking your workspace access…</div></PageFrame>;
  if (user?.role !== "vendor" || !vendorRegistered) return <PageFrame><div className="mx-auto grid min-h-[60vh] max-w-xl place-items-center text-center"><span className="grid size-16 place-items-center rounded-2xl bg-brand/10 text-brand"><Store className="size-8" /></span><p className="mt-6 text-xs font-bold uppercase tracking-[0.22em] text-brand">Vendor access required</p><h1 className="mt-3 text-3xl font-bold tracking-tight">Create a vendor account before entering</h1><p className="mt-3 text-ink-muted">The vendor dashboard is only available to approved vendor accounts. Sign up or sign in as a vendor to display products and manage your store.</p><div className="mt-7 flex flex-wrap justify-center gap-3"><Link href="/sign-up?role=vendor" className="inline-flex items-center gap-2 rounded-full bg-brand px-5 py-3 text-sm font-bold text-brand-ink">Sign up as vendor <ArrowRight className="size-4" /></Link><Link href="/sign-in?role=vendor" className="rounded-full border border-line px-5 py-3 text-sm font-bold hover:border-brand">Sign in as vendor</Link></div><Link href="/" className="mt-5 text-sm font-semibold text-ink-muted hover:text-brand">Continue shopping as a user</Link></div></PageFrame>;
  const vendorName = user.storeName ?? "Your store";
  return <PageFrame><main className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8 lg:py-10"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[0.22em] text-brand"><span className="size-2 rounded-full bg-brand shadow-[0_0_10px_var(--brand)]" /> Vendor workspace</div><h1 className="mt-2 text-3xl font-bold tracking-tight sm:text-4xl">{vendorName}</h1><p className="mt-2 text-ink-muted">Your catalog is live in Aura Market.</p></div><div className="flex gap-2"><Link href="/admin" className="hidden rounded-full border border-line px-4 py-2.5 text-sm font-semibold sm:inline-flex">Admin console</Link><Link href="/vendor/products/new" className="inline-flex items-center gap-2 rounded-full bg-brand px-4 py-2.5 text-sm font-bold text-brand-ink"><Plus className="size-4" /> Add product</Link></div></div><section className="mt-8"><PortalSwitcher active="vendor" /></section><div className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4"><Metric label="Live products" value="24" note="3 drafts" icon={Package} /><Metric label="Store visits" value="8,492" note="+18.4% this week" icon={Eye} /><Metric label="This month" value="$12.8k" note="+9.1% vs last month" icon={TrendingUp} /><Metric label="Open orders" value="18" note="5 need dispatch" icon={ReceiptText} /></div><div className="mt-8 grid gap-8 lg:grid-cols-[1fr_300px]"><section><div className="mb-4 flex items-center justify-between"><div><h2 className="text-xl font-bold">Your displayed catalog</h2><p className="mt-1 text-sm text-ink-muted">Products customers can discover and buy today.</p></div><span className="hidden items-center gap-1 text-sm font-bold text-brand sm:flex">Manage catalog <ArrowRight className="size-4" /></span></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{products.slice(0, 6).map((product) => <article key={product.id} className="rounded-2xl border border-line bg-panel p-2.5"><Thumb product={product} className="aspect-square rounded-xl" /><div className="p-1.5"><p className="mt-2 line-clamp-2 text-sm font-semibold">{product.name}</p><div className="mt-2 flex items-center justify-between"><span className="font-bold">{money(product.price).replace(".00", "")}</span><span className="text-[11px] font-semibold text-good">In stock</span></div></div></article>)}</div><Link href="/vendor/products/new" className="mt-4 flex items-center justify-center gap-2 rounded-2xl border border-dashed border-brand/50 bg-brand/5 p-4 text-sm font-bold text-brand hover:bg-brand/10"><ImagePlus className="size-5" /> Display a new product</Link></section><aside className="space-y-3"><div className="rounded-2xl border border-brand/30 bg-brand/10 p-5"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-brand text-brand-ink"><Store className="size-5" /></span><div><p className="font-bold">Store health</p><p className="text-sm text-ink-muted">Looking strong</p></div></div><div className="mt-5 space-y-3 text-sm"><div className="flex justify-between"><span className="text-ink-muted">Catalog completeness</span><b>92%</b></div><div className="h-2 rounded-full bg-canvas/60"><div className="h-full w-[92%] rounded-full bg-brand" /></div><div className="flex justify-between"><span className="text-ink-muted">Response time</span><b className="text-good">&lt; 2 hrs</b></div></div></div><div className="rounded-2xl border border-line bg-panel p-5"><h3 className="font-bold">Quick actions</h3><div className="mt-3 space-y-2"><Link href="/vendor/products/new" className="flex items-center justify-between rounded-xl bg-soft px-3 py-3 text-sm font-semibold"><span className="flex items-center gap-2"><Plus className="size-4 text-brand" /> Add product</span><ArrowRight className="size-4" /></Link><span className="flex items-center justify-between rounded-xl bg-soft px-3 py-3 text-sm font-semibold"><span className="flex items-center gap-2"><ReceiptText className="size-4 text-brand" /> View orders</span><span className="text-xs text-ink-muted">Soon</span></span><span className="flex items-center justify-between rounded-xl bg-soft px-3 py-3 text-sm font-semibold"><span className="flex items-center gap-2"><Settings2 className="size-4 text-brand" /> Store settings</span><span className="text-xs text-ink-muted">Soon</span></span></div></div></aside></div></main></PageFrame>;
}
function PageFrame({ children }: { children: React.ReactNode }) { return <div className="theme-aura min-h-screen bg-canvas pb-24 text-ink md:pb-0 portal-glow"><StoreHeader />{children}<BottomNav /></div>; }
function Metric({ label, value, note, icon: Icon }: { label: string; value: string; note: string; icon: typeof Package }) { return <div className="rounded-2xl border border-line bg-panel p-4"><span className="grid size-9 place-items-center rounded-xl bg-brand/10 text-brand"><Icon className="size-4" /></span><p className="mt-4 text-sm text-ink-muted">{label}</p><p className="mt-1 text-2xl font-bold tracking-tight">{value}</p><p className="mt-1 text-xs font-semibold text-good">{note}</p></div>; }
